    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no',
  });

  const client = res;
  clients.add(client);
  client.write(`data: {"type":"connected"}\n\n`);

  req.on('close', () => {
    clients.delete(client);
  });
});

