const express = require('express');
const cors = require('cors');
const path = require('path');
const { PGLite } = require('@electric-sql/pglite');

const app = express();
app.use(cors());
app.use(express.json());

let db;
const clients = new Set();

// SSE endpoint
app.get('/api/stream', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no',
  });

  const client = res;
  clients.add(client);
  client.write(`data: {"type":"connected"}\n\n`);

  req.on('close', () => {
    clients.delete(client);
  });
});

function broadcast(event, data) {
  const msg = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const client of clients) {
    try {
      client.write(msg);
    } catch (e) {
      // client disconnected
    }
  }
}

// Board state endpoint
app.get('/api/board', async (req, res) => {
  try {
    const columns = await db.query('SELECT id, title, position FROM columns ORDER BY position');
    const result = [];

    for (const col of columns.rows) {
      const cards = await db.query(
        'SELECT id, column_id, text, position, created_at FROM cards WHERE column_id = $1 ORDER BY position',
        [col.id]
      );
      result.push({
        id: col.id,
        title: col.title,
        position: col.position,
        cards: cards.rows,
      });
    }

    res.json(result);
  } catch (err) {
    console.error('Error fetching board:', err);
    res.status(500).json({ error: 'Failed to fetch board' });
  }
});

