      if (before.rows.length > 0) {
        // Find the card immediately after beforeId
        const nextCard = await db.query(
          'SELECT MIN(position) as min_pos FROM cards WHERE column_id = $1 AND position > $2',
          [columnId, before.rows[0].position]
