  });

  const client = res;
  clients.add(client);
  client.write(`data: {"type":"connected"}\n\n`);

  req.on('close', () => {
    clients.delete(client);
  });
});

function broadcast(event, data) {
  const msg = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const client of clients) {
    try {
      client.write(msg);
    } catch (e) {
      // client disconnected
    }
  }
}

